-- Restrict direct notification inserts to verifiable story reactions and replies.
-- Likes, comments, follows and messages are generated by trusted database triggers.

drop policy if exists "Actors create notifications" on public.notifications;

create policy "Users create notifications for real story interactions"
on public.notifications
for insert
to authenticated
with check (
  actor_id = (select auth.uid())
  and recipient_id <> (select auth.uid())
  and is_read = false
  and created_at >= now() - interval '5 minutes'
  and created_at <= now() + interval '1 minute'
  and post_id is null
  and comment_id is null
  and (
    (
      type = 'story_reaction'
      and exists (
        select 1
        from public.story_reactions r
        join public.stories s on s.id = r.story_id
        where r.story_id = notifications.story_id
          and r.user_id = (select auth.uid())
          and s.user_id = notifications.recipient_id
          and notifications.message = 'a réagi ' || r.reaction || ' à ta story.'
      )
    )
    or
    (
      type = 'story_reply'
      and exists (
        select 1
        from public.story_replies r
        join public.stories s on s.id = r.story_id
        where r.story_id = notifications.story_id
          and r.sender_id = (select auth.uid())
          and s.user_id = notifications.recipient_id
          and notifications.message = 't’a envoyé une réponse à ta story.'
      )
    )
  )
);
